-- ============================================
-- LUMA — Thème 12 : 3e scénario COURT x4 — Acheter un billet combiné
-- ============================================


update scenarios set content = '{"characters": {"clerk": "le vendeur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "clerk", "text": "Welcome! Would you like a standard ticket, or our combo ticket including the temporary exhibit?", "text_fr": "Bienvenue ! Vous voulez un billet standard, ou notre billet combiné incluant l''exposition temporaire ?", "choices": [{"text": "What''s in the temporary exhibit right now?", "text_fr": "Qu''est-ce qu''il y a dans l''exposition temporaire en ce moment ?", "next": "n2"}, {"text": "I''ll take the combo ticket, I want to see everything.", "text_fr": "Je vais prendre le billet combiné, je veux tout voir.", "next": "n2b"}]}, "n2": {"speaker": "clerk", "text": "It''s a fascinating collection of ancient Egyptian artifacts, quite popular right now.", "text_fr": "C''est une fascinante collection d''artefacts égyptiens anciens, assez populaire en ce moment.", "choices": [{"text": "That sounds amazing, I''ll take the combo ticket then.", "text_fr": "Ça a l''air génial, je prends le billet combiné alors.", "next": "n3"}, {"text": "I think I''ll just do the standard ticket this time, thank you.", "text_fr": "Je pense que je vais juste faire le billet standard cette fois, merci.", "next": "n3b"}]}, "n2b": {"speaker": "clerk", "text": "Great choice, that exhibit is definitely worth it!", "text_fr": "Excellent choix, cette exposition en vaut vraiment la peine !", "choices": [{"text": "I''m excited to see it, thank you!", "text_fr": "J''ai hâte de la voir, merci !", "next": "n3"}]}, "n3": {"speaker": "clerk", "text": "That''ll be $25 for the combo ticket. Cash or card?", "text_fr": "Ça fera 25$ pour le billet combiné. Espèces ou carte ?", "choices": [{"text": "Card, please.", "text_fr": "Carte, s''il vous plaît.", "next": "n4"}]}, "n3b": {"speaker": "clerk", "text": "No problem, that''ll be $15 for the standard ticket. Cash or card?", "text_fr": "Aucun problème, ça fera 15$ pour le billet standard. Espèces ou carte ?", "choices": [{"text": "Card, please.", "text_fr": "Carte, s''il vous plaît.", "next": "n4"}]}, "n4": {"speaker": "clerk", "text": "Perfect, here''s your ticket and a map of the museum. Enjoy your visit!", "text_fr": "Parfait, voici votre billet et un plan du musée. Bonne visite !", "choices": [{"text": "Thank you so much, I''m looking forward to it.", "text_fr": "Merci beaucoup, j''ai hâte.", "next": "end_ticketed"}]}, "end_ticketed": {"speaker": "clerk", "text": "Enjoy the exhibits, and don''t miss the gift shop on your way out!", "text_fr": "Profitez des expositions, et ratez pas la boutique de souvenirs en sortant !", "end": true, "ending_label": "Billet acheté, visite prête à commencer 🎟️🏛️"}}}'::jsonb, is_playable = true
where title = 'Acheter un billet combiné'
  and theme_id = (select id from scenario_themes where position = 12 and language_id = (select id from languages where code = 'en'));
